@import "@fontsource-variable/figtree";
@import "@fontsource/ibm-plex-mono/400.css";

/* Light (faithful): white page, ink #1a1d21, grey body #42474d, quieter #878e99. Violet
   #612fff for every action. Lavender #f0efff wash (announcement), cool grey #f6f7f8 footer
   and fields, hairlines #e8eaed. The five product gradients take their stops from highlight
   and chart-1…5. */
:root {
  --background: #ffffff;
  --foreground: #1a1d21;
  --card: #ffffff;
  --card-foreground: #1a1d21;
  --popover: #ffffff;
  --popover-foreground: #1a1d21;
  --primary: #612fff;
  --primary-foreground: #ffffff;
  --secondary: #f6f7f8;
  --secondary-foreground: #1a1d21;
  --muted: #f6f7f8;
  --muted-foreground: #545b63;
  --accent: #f0efff;
  --accent-foreground: #1a1d21;
  --destructive: #f80f55;
  --destructive-foreground: #ffffff;
  --border: #e8eaed;
  --input: #d7dbe0;
  --ring: #612fff;
  --highlight: #ff4f42;
  --highlight-foreground: #ffffff;
  --glow: #7043ff;
  --chart-1: #ff8e3c;
  --chart-2: #d200a3;
  --chart-3: #072fff;
  --chart-4: #8415f3;
  --chart-5: #0be2d6;
  --sidebar: #f6f7f8;
  --sidebar-foreground: #1a1d21;
  --sidebar-primary: #612fff;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #f0efff;
  --sidebar-accent-foreground: #1a1d21;
  --sidebar-border: #e8eaed;
  --sidebar-ring: #612fff;

  --typeface-body: "Figtree Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Figtree Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.375rem;
  /* 1440px wide: blocks add 48px side padding from lg, leaving the original's 1344px row */
  --page-width: 90rem;
  --page-gutter: 1.5rem;
  --section-y: 5rem;
}

/* Dark sibling: the original's graphite bands. Page #1f2225, panels #2f3237, white ink,
   cool grey #a0a7b1 secondary text, the violet a step lighter so it holds on graphite. */
.dark {
  --background: #1f2225;
  --foreground: #ffffff;
  --card: #2f3237;
  --card-foreground: #ffffff;
  --popover: #2f3237;
  --popover-foreground: #ffffff;
  --primary: #7043ff;
  --primary-foreground: #ffffff;
  --secondary: #2f3237;
  --secondary-foreground: #ffffff;
  --muted: #2f3237;
  --muted-foreground: #a0a7b1;
  --accent: #34305a;
  --accent-foreground: #ffffff;
  --destructive: #f80f55;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 12%);
  --input: rgb(255 255 255 / 18%);
  --ring: #8f6bff;
  --highlight: #ff4f42;
  --highlight-foreground: #ffffff;
  --glow: #8f6bff;
  --chart-1: #ff8e3c;
  --chart-2: #d200a3;
  --chart-3: #0558fa;
  --chart-4: #8415f3;
  --chart-5: #0be2d6;
  --sidebar: #2f3237;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #7043ff;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #34305a;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 12%);
  --sidebar-ring: #8f6bff;
}
